// === Tab: mySketch ===
// ============================================================
// OpenCodeとGitHub Copilotに手伝ってもらったけど、
// 結局、動きのバリエーションは自分で考えることになったため、
// AI時代もこんな感じで創作していくんだろうな〜と思った次第です
// とはいえコードを読むとボリュームはすごいしめんどくさいこといっぱいやってくれてるし、
// ありがたいっすね〜
// ============================================================

// ---- 定数 ----
const MAX_TRACKERS   = 60;
const SPAWN_INTERVAL = 5;
const TRAIL_LEN      = 16;
const SPAWN_RADIUS   = 700;
const TARGET_SPEED   = 10.0;
const CAM_LAG        = 0.1;

// ---- グローバル ----
let target;
let trackers   = [];
let collisions = [];
let cam;
let cleanMode  = false;

// ============================================================
//  セットアップ
// ============================================================
function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(RGB, 255, 255, 255, 255);
  target = new Target();
  cam    = target.pos.copy();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
  if (key === 'c' || key === 'C') cleanMode = !cleanMode;
}

// ============================================================
//  メインループ
// ============================================================
function draw() {
  background(cleanMode ? 255 : color(8, 8, 20));

  // カメラ：ターゲットをなめらかに追尾
  cam.x += (target.pos.x - cam.x) * CAM_LAG;
  cam.y += (target.pos.y - cam.y) * CAM_LAG;

  let ox = width  / 2 - cam.x;
  let oy = height / 2 - cam.y;

  push();
  translate(ox, oy);

  // ---- Target ----
  target.update(trackers);
  target.draw();

  // ---- Tracker 生成 ----
  if (frameCount % SPAWN_INTERVAL === 0 && trackers.length < MAX_TRACKERS) {
    trackers.push(new Tracker(target));
  }

  // ---- Tracker 更新・描画 ----
  for (let i = trackers.length - 1; i >= 0; i--) {
    trackers[i].update(target, trackers);
    if (trackers[i].dead) {
      if (!trackers[i].silent) spawnCollision(trackers[i].pos.copy(), trackers[i].col);
      trackers.splice(i, 1);
    } else {
      trackers[i].draw();
    }
  }

  // ---- Tracker 同士の衝突判定 ----
  for (let i = trackers.length - 1; i >= 1; i--) {
    for (let j = i - 1; j >= 0; j--) {
      if (trackers[i].dead || trackers[j].dead) continue;
      if (p5.Vector.dist(trackers[i].pos, trackers[j].pos) < 24) {
        let mid = p5.Vector.add(trackers[i].pos, trackers[j].pos).mult(0.5);
        // 衝突地点が画面内のときのみ Collision を生成
        let mx = mid.x - (cam.x - width  / 2);
        let my = mid.y - (cam.y - height / 2);
        if (mx >= 0 && mx <= width && my >= 0 && my <= height) {
          // 2つの Tracker の色を平均して渡す
          let col = trackers[i].col.map((v, k) => (v + trackers[j].col[k]) / 2);
          spawnCollision(mid, col);
        }
        trackers[i].dead = true;
        trackers[j].dead = true;
      }
    }
  }
  for (let i = trackers.length - 1; i >= 0; i--) {
    if (trackers[i].dead) trackers.splice(i, 1);
  }

  // ---- Collision 更新・描画 ----
  for (let i = collisions.length - 1; i >= 0; i--) {
    collisions[i].update();
    if (collisions[i].dead) {
      collisions.splice(i, 1);
    } else {
      collisions[i].draw();
    }
  }

  pop();
}

// ============================================================
//  Collision 生成
// ============================================================
function spawnCollision(pos, col) {
  collisions.push(new Collision(pos, col));
}

// ============================================================
//  Target クラス
// ============================================================
class Target {
  constructor() {
    this.pos        = createVector(width / 2, height / 2);
    this.vel        = p5.Vector.random2D().mult(TARGET_SPEED);
    this.acc        = createVector(0, 0);
    this.waypoint   = this._newWaypoint();
    this.size       = 42;
  }

  _newWaypoint() {
    return createVector(
      random(width  * 0.1, width  * 0.9),
      random(height * 0.1, height * 0.9)
    );
  }

  update(trackers) {
    // ---- Tracker からの逃避力 ----
    let flee        = createVector(0, 0);
    let nearest     = null;
    let nearestDist = Infinity;
    for (let m of trackers) {
      let d = p5.Vector.dist(this.pos, m.pos);
      if (d < nearestDist) { nearestDist = d; nearest = m; }
      if (d < 280) {
        let away = p5.Vector.sub(this.pos, m.pos).normalize().mult(280 / (d + 1));
        flee.add(away);
      }
    }

    // 最接近 Tracker が近づいたらその逆方向にウェイポイントを更新
    if (nearest && nearestDist < 200) {
      let awayDir = p5.Vector.sub(this.pos, nearest.pos).normalize();
      this.waypoint = p5.Vector.add(
        this.pos,
        awayDir.mult(random(180, 350))
      );
    }

    // ---- ウェイポイント追尾 ----
    let toWay = p5.Vector.sub(this.waypoint, this.pos);
    if (toWay.mag() < 60) {
      this.waypoint = this._newWaypoint();
      toWay = p5.Vector.sub(this.waypoint, this.pos);
    }

    let desired = toWay.normalize().mult(TARGET_SPEED);

    this.acc = p5.Vector.sub(desired, this.vel).limit(0.5);
    this.acc.add(flee.limit(TARGET_SPEED * 1.2));

    this.vel.add(this.acc);
    this.vel.limit(TARGET_SPEED * 2.0);
    if (this.vel.mag() < TARGET_SPEED * 0.5) this.vel.setMag(TARGET_SPEED * 0.5);
    this.pos.add(this.vel);
  }

  draw() {
    push();
    translate(this.pos.x, this.pos.y);
    rotate(this.vel.heading());

    let s        = this.size;
    let barrierR = s * 1.2;

    if (cleanMode) {
      // ---- cleanMode：黒塗り三角形のみ ----
      noStroke();
      fill(0);
      triangle(
         s,       0,
        -s * 0.6, -s * 0.55,
        -s * 0.6,  s * 0.55
      );
    } else {
      // ---- 通常：白線・塗りつぶしなし ----
      stroke(255);
      strokeWeight(2.5);
      noFill();
      triangle(
         s,       0,
        -s * 0.6, -s * 0.55,
        -s * 0.6,  s * 0.55
      );
    }

    pop();
  }
}

// ============================================================
//  Tracker クラス
// ============================================================
const TRACKER_TYPES = ['fast', 'spiral', 'overshoot', 'drunk', 'intercept'];

class Tracker {
  constructor(target) {
    this.type = random(TRACKER_TYPES);
    this.dead = false;
    this.life = 0;

    // 画面外4辺のいずれかからランダムに出現（カメラ基準）
    let margin = random(50, 150);
    let side   = floor(random(4)); // 0:上 1:下 2:左 3:右
    let sx, sy;
    if (side === 0) {
      sx = cam.x - width  / 2 + random(width);
      sy = cam.y - height / 2 - margin;
    } else if (side === 1) {
      sx = cam.x - width  / 2 + random(width);
      sy = cam.y + height / 2 + margin;
    } else if (side === 2) {
      sx = cam.x - width  / 2 - margin;
      sy = cam.y - height / 2 + random(height);
    } else {
      sx = cam.x + width  / 2 + margin;
      sy = cam.y - height / 2 + random(height);
    }
    this.pos = createVector(sx, sy);

    this.vel = p5.Vector.sub(target.pos, this.pos).normalize().mult(this._initSpeed());
    this.acc = createVector(0, 0);

    this.trail         = [];
    this.spiralAngle   = random(TWO_PI);
    this.spiralSpeed   = random(0.10, 0.18) * (random() > 0.5 ? 1 : -1);
    this.spiralRadius  = random(100, 220);
    this.overshootDone = false;
    this.drunkSeedX    = random(1000);
    this.drunkSeedY    = random(1000);
    this.drunkT        = random(100);

    this.col = this._pickColor();
  }

  _initSpeed() {
    return { fast: random(12, 18), spiral: random(6, 10), overshoot: random(8, 13), drunk: random(6, 12), intercept: random(10, 16) }[this.type];
  }

  _pickColor() {
    return { fast: [255, 80, 40], spiral: [60, 255, 160], overshoot: [255, 200, 50], drunk: [220, 80, 255], intercept: [255, 160, 220] }[this.type];
  }

  update(target, trackers) {
    if (this.dead) return;
    this.life++;

    let toTarget = p5.Vector.sub(target.pos, this.pos);
    let toTargetDist     = toTarget.mag();

    if (toTargetDist < 18) { this.dead = true; return; }

    // 画面外450px以上に出たら静かに消滅（Collision なし）
    let screenX = this.pos.x - (cam.x - width  / 2);
    let screenY = this.pos.y - (cam.y - height / 2);
    if (screenX < -450 || screenX > width  + 450 ||
        screenY < -450 || screenY > height + 450) {
      this.dead   = true;
      this.silent = true;
      return;
    }

    this._steer(target, toTarget, toTargetDist, trackers);

    this.vel.add(this.acc);
    this._limitSpeed();
    this.pos.add(this.vel);
    this.acc.mult(0);

    this.trail.push(this.pos.copy());
    if (this.trail.length > TRAIL_LEN) this.trail.shift();
  }

  _steer(target, toTarget, toTargetDist, trackers) {
    switch (this.type) {
      case 'fast': {
        let desired = toTarget.copy().normalize().mult(18);
        let steer   = p5.Vector.sub(desired, this.vel).limit(0.9);
        this.acc.add(steer);
        break;
      }
      case 'spiral': {
        this.spiralAngle += this.spiralSpeed;
        let toTargetNorm   = toTarget.copy().normalize();
        let perp   = createVector(-toTargetNorm.y, toTargetNorm.x);
        let offset = p5.Vector.add(
          target.pos,
          perp.copy().mult(sin(this.spiralAngle) * this.spiralRadius)
        );
        let toOff  = p5.Vector.sub(offset, this.pos).normalize().mult(14);
        let steer  = p5.Vector.sub(toOff, this.vel).limit(0.7);
        this.acc.add(steer);
        break;
      }
      case 'overshoot': {
        if (!this.overshootDone && toTargetDist < 100) this.overshootDone = true;
        let aimPos  = this.overshootDone
          ? target.pos
          : p5.Vector.add(target.pos, this.vel.copy().normalize().mult(-150));
        let desired = p5.Vector.sub(aimPos, this.pos).normalize().mult(14);
        let steer   = p5.Vector.sub(desired, this.vel).limit(0.6);
        this.acc.add(steer);
        break;
      }
      case 'drunk': {
        this.drunkT += 0.018;
        let nx       = (noise(this.drunkSeedX + this.drunkT)       - 0.5) * 2;
        let ny       = (noise(this.drunkSeedY + this.drunkT + 100) - 0.5) * 2;
        let noiseVec = createVector(nx, ny).mult(0.55);
        let homingStr = constrain(map(toTargetDist, 60, 500, 0, 0.18), 0, 0.18);
        let homing    = toTarget.copy().normalize().mult(homingStr);
        let steer     = p5.Vector.add(noiseVec, homing).limit(0.5);
        this.acc.add(steer);
        break;
      }
      case 'intercept': {
        let leadTime  = constrain(toTargetDist / 18, 5, 60);
        let predicted = p5.Vector.add(target.pos, target.vel.copy().mult(leadTime));
        let desired   = p5.Vector.sub(predicted, this.pos).normalize().mult(16);
        let steer     = p5.Vector.sub(desired, this.vel).limit(0.7);
        this.acc.add(steer);

        // 他の Tracker から距離80px以内なら反発
        if (trackers) {
          for (let other of trackers) {
            if (other === this || other.dead) continue;
            let d = p5.Vector.dist(this.pos, other.pos);
            if (d < 80 && d > 0) {
              let repel = p5.Vector.sub(this.pos, other.pos).normalize().mult((80 - d) / 80 * 0.6);
              this.acc.add(repel);
            }
          }
        }
        break;
      }
    }
  }

  _limitSpeed() {
    let maxS = { fast: 22, spiral: 16, overshoot: 17, drunk: 15, intercept: 20 }[this.type];
    let minS = { fast: 8,  spiral: 7,  overshoot: 6,  drunk: 5,  intercept: 7  }[this.type];
    let s = this.vel.mag();
    if (s > maxS) this.vel.setMag(maxS);
    if (s < minS) this.vel.setMag(minS);
  }

  draw() {
    if (this.trail.length < 2) return;
    let [r, g, b] = this.col;

    // トレイル
    noFill();
    for (let i = 1; i < this.trail.length; i++) {
      let t  = i / this.trail.length;
      let p0 = this.trail[i - 1];
      let p1 = this.trail[i];
      if (cleanMode) {
        stroke(0);
      } else {
        stroke(r, g, b);
      }
      strokeWeight(t * 3.5);
      line(p0.x, p0.y, p1.x, p1.y);
    }

    let tip  = this.pos;
    let tail = this.trail[this.trail.length - 2];
    let ang  = p5.Vector.sub(tip, tail).heading();

    push();
    translate(tip.x, tip.y);
    rotate(ang);

    // 機体：二等辺三角形（先端が右＝進行方向）
    noStroke();
    fill(cleanMode ? color(0) : color(r, g, b));
    triangle(34, 0, -19, -13, -19, 13);

    pop();
  }
}

// ============================================================
//  Collision クラス（波紋エフェクト）
// ============================================================
class Collision {
  constructor(pos, col) {
    this.pos     = pos;
    this.col     = col || [255, 220, 100];
    this.dead    = false;
    // 時間差で広がる波紋を複数枚生成
    this.ripples = [
      { delay: 0,  maxR: 80,  maxLife: 40 },
      { delay: 6,  maxR: 120, maxLife: 45 },
      { delay: 12, maxR: 60,  maxLife: 35 },
    ].map(r => ({ ...r, life: -r.delay }));
  }

  update() {
    for (let r of this.ripples) r.life++;
    // 全波紋が寿命を終えたら消滅
    if (this.ripples.every(r => r.life >= r.maxLife)) this.dead = true;
  }

  draw() {
    noFill();
    for (let r of this.ripples) {
      if (r.life < 0) continue;               // delay 中はスキップ
      let t = r.life / r.maxLife;             // 0→1 で進行
      let radius = r.maxR * t;               // 外側に広がる
      let colorAlpha  = (1 - t) * (cleanMode ? 200 : 180);  // フェードアウト
      let weight = (1 - t) * 3 + 0.5;       // 細くなる

      if (cleanMode) {
        stroke(0, colorAlpha);
      } else {
        let [r, g, b] = this.col;
        stroke(r, g, b, colorAlpha);
      }
      strokeWeight(weight);
      ellipse(this.pos.x, this.pos.y, radius * 2, radius * 2);
    }
  }
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
